static void PCAP_NORETURN
opt_error(opt_state_t *opt_state, const char *fmt, ...)
{
        va_list ap;

        if (opt_state->errbuf != NULL) {
                va_start(ap, fmt);
                (void)pcap_vsnprintf(opt_state->errbuf,
